result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/app.py", "content": """"Chemistry calculation HTTP API."""
from typing import Dict

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI(title="Chemistry Calculations API")

ATOMIC_WEIGHTS = {
    "H": 1.008,
    "C": 12.011,
    "N": 14.007,
    "O": 15.999,
    "Na": 22.990,
    "S": 32.06,
    "Cl": 35.45,
}


def molar_mass(formula: str) -> float:
    """Compute molar mass of a chemical formula (supports nested parentheses)."""
    formula = formula.strip()
    if not formula:
        raise ValueError("empty formula")

    def parse(s: str, pos: int = 0):
        """Return (mass, next_pos). Raises ValueError on malformed input."""
        total = 0.0
        n = len(s)
        while pos < n:
            ch = s[pos]
            if ch == "(":
                inner, pos = parse(s, pos + 1)
                if pos >= n or s[pos] != ")":
                    raise ValueError("unbalanced parenthesis")
                pos += 1
                count, pos = _number(s, pos, default=1)
                total += inner * count
            elif ch == ")":
                return total, pos
            elif ch.isupper():
                start = pos
                pos += 1
                while pos < n and s[pos].islower():
                    pos += 1
                symbol = s[start:pos]
                if symbol not in ATOMIC_WEIGHTS:
                    raise ValueError(f"unknown element {symbol!r}")
                count, pos = _number(s, pos, default=1)
                total += ATOMIC_WEIGHTS[symbol] * count
            else:
                raise ValueError(f"unexpected character {ch!r}")
        return total, pos

    mass, end = parse(formula)
    if end != len(formula):
        raise ValueError(f"trailing characters at position {end}")
    return mass


def _number(s: str, pos: int, default: int):
    digits = ""
    while pos < len(s) and s[pos].isdigit():
        digits += s[pos]
        pos += 1
    return (int(digits) if digits else default), pos


class MolarMassRequest(BaseModel):
    formula: str


class LimitingRequest(BaseModel):
    equation: str
    grams: Dict[str, float]


class MolarMassResponse(BaseModel):
    formula: str
    molar_mass: float


class LimitingResponse(BaseModel):
    limiting_reagent: str
    products: Dict[str, float]


@app.post("/molar-mass")
def compute_molar_mass(req: MolarMassRequest):
    try:
        mass = molar_mass(req.formula)
    except ValueError as e:
        raise HTTPException(status_code=422, detail=str(e))
    return {"formula": req.formula.strip(), "molar_mass": round(mass, 4)}


def parse_equation(equation: str):
    """Parse '2 H2 + O2 -> 2 H2O' into ({'H2':2,'O2':1}, {'H2O':2})."""
    try:
        lhs, rhs = equation.split("->")
    except ValueError:
        raise ValueError("equation must contain '->'")

    def side(tokens: str):
        species: Dict[str, int] = {}
        for token in tokens.split("+"):
            token = token.strip()
            if not token:
                continue
            parts = token.split()
            if len(parts) == 2 and parts[0].isdigit() and parts[0].lstrip("-").isdigit():
                coeff, form = int(parts[0]), parts[1]
            elif len(parts) == 1:
                coeff, form = 1, parts[0]
            else:
                raise ValueError(f"malformed term {token!r}")
            # validate the formula parses; strip any leading digit glued to it
            molar_mass(form)
            species[form] = species.get(form, 0) + coeff
        return species

    reactants = side(lhs)
    products = side(rhs)
    if not reactants or not products:
        raise ValueError("equation must have reactants and products")
    return reactants, products


@app.post("/limiting")
def compute_limiting(req: LimitingRequest):
    try:
        reactants, products = parse_equation(req.equation)
    except ValueError as e:
        raise HTTPException(status_code=422, detail=str(e))

    available_moles: Dict[str, float] = {}
    for formula, grams in req.grams.items():
        try:
            mm = molar_mass(formula)
        except ValueError as e:
            raise HTTPException(status_code=422, detail=f"{formula}: {e}")
        available_moles[formula] = grams / mm

    extents: Dict[str, float] = {}
    for formula, coeff in reactants.items():
        if formula not in available_moles:
            raise HTTPException(
                status_code=422,
                detail=f"no grams provided for reactant {formula!r}",
            )
        extents[formula] = available_moles[formula] / coeff

    limiting = min(extents, key=extents.get)
    extent = extents[limiting]

    yields: Dict[str, float] = {}
    for formula, coeff in products.items():
        yields[formula] = round(extent * coeff * molar_mass(formula), 4)

    return {"limiting_reagent": limiting, "products": yields}
